ADD MAP FLEASGNM VERSION 1
    DEVICE IS 3270 SIZE IS 24 BY 80
    RECORDS ARE FLEWORK EMPLOYEE VEHICLE
    .
    LITERAL 'FLEASGN'                      ROW 1  COLUMN 2  INTENSITY BRIGHT.
    LITERAL 'ASSIGN COMPANY CAR'           ROW 1  COLUMN 31 INTENSITY BRIGHT.
    LITERAL 'EMPLOYEE ID'                  ROW 4  COLUMN 2.
    FIELD WK-EMPID                         ROW 4  COLUMN 16 LENGTH 8 UNPROTECTED.
    FIELD EM-FORN                          ROW 4  COLUMN 28 LENGTH 15 PROTECTED.
    FIELD EM-SURN                          ROW 4  COLUMN 44 LENGTH 20 PROTECTED.
    LITERAL 'GRADE'                        ROW 5  COLUMN 2.
    FIELD EM-GRD                           ROW 5  COLUMN 16 LENGTH 2  PROTECTED.
    LITERAL 'VEHICLE ID'                   ROW 8  COLUMN 2.
    FIELD WK-VEHID                         ROW 8  COLUMN 16 LENGTH 8 UNPROTECTED.
    FIELD VH-PLATE                         ROW 8  COLUMN 28 LENGTH 8  PROTECTED.
    FIELD VH-MAKE                          ROW 8  COLUMN 38 LENGTH 12 PROTECTED.
    LITERAL 'START DATE'                   ROW 10 COLUMN 2.
    FIELD AS-STRT                          ROW 10 COLUMN 16 LENGTH 8 UNPROTECTED
        EDIT PICTURE IS 9(8) REQUIRED.
    LITERAL 'REASON NC/RP/PL'              ROW 11 COLUMN 2.
    FIELD AS-RSN                           ROW 11 COLUMN 18 LENGTH 2 UNPROTECTED.
    FIELD WK-MSG                           ROW 22 COLUMN 2  LENGTH 60 PROTECTED.
    LITERAL 'ENTER=ASSIGN  PF3=MENU'       ROW 24 COLUMN 2.
